"<script>\n"
"'use strict';\n"
"const $ = id => document.getElementById(id);\n"
"const LS_SIGHTS = 'navalm.sights', LS_SETUP = 'navalm.setup';\n"
"\n"
"/* ---------- formatting ---------- */\n"
"const pad = (n,w)=>String(n).padStart(w,'0');\n"
"function dm(x,degw){\n"
"  const s = x<0?'\\u2212':''; x=Math.abs(x);\n"
"  let d=Math.floor(x), m=(x-d)*60;\n"
"  if(m>=59.95){m=0;d++;}\n"
"  return s+pad(d,degw)+'\\u00b0 '+(m<10?'0':'')+m.toFixed(1)+'\\u2032';\n"
"}\n"
"const alt = x=>dm(x,2);\n"
"/* single-body lookups keep hundredths of a minute; tables stay at tenths */\n"
"function dm2(x,degw){\n"
"  const s = x<0?'\\u2212':''; x=Math.abs(x);\n"
"  let d=Math.floor(x), m=(x-d)*60;\n"
"  if(m>=59.995){m=0;d++;}\n"
"  return s+pad(d,degw)+'\\u00b0 '+(m<10?'0':'')+m.toFixed(2)+'\\u2032';\n"
"}\n"
"const gha2 = x=>dm2(((x%360)+360)%360,3);\n"
"/* right ascension as degrees, minutes and seconds */\n"
"function radms(x){\n"
"  let a=((x%360)+360)%360;\n"
"  let d=Math.floor(a), m=Math.floor((a-d)*60), s=((a-d)*60-m)*60;\n"
"  if(s>=59.95){s=0;m++;}\n"
"  if(m>=60){m=0;d=(d+1)%360;}\n"
"  return pad(d,3)+'\\u00b0 '+pad(m,2)+'\\u2032 '+(s<10?'0':'')+s.toFixed(1)+'\\u2033';\n"
"}\n"
"const lat2 = x=>(x<0?'S ':'N ')+dm2(Math.abs(x),2);\n"
"const gha = x=>dm(((x%360)+360)%360,3);\n"
"const lat = x=>(x<0?'S ':'N ')+dm(Math.abs(x),2);\n"
"const lon = x=>(x<0?'W ':'E ')+dm(Math.abs(x),3);\n"
"function mins(x){\n"
"  const r=Math.round(x*10)/10;\n"
"  if(r===0) return '0.0\\u2032';\n"
"  return (r<0?'\\u2212':'+')+Math.abs(r).toFixed(1)+'\\u2032';\n"
"}\n"
"const num=(x,n)=>Number(x).toFixed(n===undefined?1:n);\n"
"\n"
"/* ---------- math typesetting (no external libraries) ---------- */\n"
"const frac=(a,b)=>`<span class=\"frac\"><span>${a}</span><span>${b}</span></span>`;\n"
"const sqrt=a=>`\\u221a<span class=\"rad\">${a}</span>`;\n"
"const v=s=>`<i>${s}</i>`;\n"
"\n"
"/* ---------- position parsing, same spirit as the TUI ---------- */\n"
"function parsePos(text,isLon){\n"
"  if(!text) return 0;\n"
"  const nums=[]; let hemi=0;\n"
"  const re=/([NSEWnsew])|(-?\\d+(?:\\.\\d+)?)/g; let m;\n"
"  while((m=re.exec(text))){\n"
"    if(m[1]){ const c=m[1].toUpperCase();\n"
"      if(c==='S'||c==='W') hemi=-1; else if(c==='N'||c==='E') hemi=1; }\n"
"    else nums.push(parseFloat(m[2]));\n"
"  }\n"
"  if(!nums.length) return 0;\n"
"  let val;\n"
"  if(nums.length===1) val=nums[0];\n"
"  else if(nums.length===2) val=Math.sign(nums[0]||1)*(Math.abs(nums[0])+nums[1]/60);\n"
"  else val=Math.sign(nums[0]||1)*(Math.abs(nums[0])+nums[1]/60+nums[2]/3600);\n"
"  if(hemi) val=hemi*Math.abs(val);\n"
"  return val;\n"
"}\n"
"\n"
"/* ---------- state ---------- */\n"
"function loadSights(){ try{ return JSON.parse(localStorage.getItem(LS_SIGHTS))||[] }catch(e){ return [] } }\n"
"function saveSights(a){ localStorage.setItem(LS_SIGHTS,JSON.stringify(a)); }\n"
"function loadSetup(){\n"
"  try{ return Object.assign(defSetup(),JSON.parse(localStorage.getItem(LS_SETUP))||{}) }\n"
"  catch(e){ return defSetup() }\n"
"}\n"
"function defSetup(){\n"
"  return {ie:0,iearc:'off',horizon:'sea',he:0,heunit:'ft',limb:'ll',\n"
"          temp:10,press:1010,drlat:34.0415,drlon:-117.3645};\n"
"}\n"
"\n"
"/* ---------- the sight form ---------- */\n"
"function renderActiveDR(){\n"
"  const st=loadSetup(), box=$('activedr');\n"
"  const la=$('f_drlat')?parsePos($('f_drlat').value):0;\n"
"  const lo=$('f_drlon')?parsePos($('f_drlon').value):0;\n"
"  const own=(la||lo);\n"
"  box.innerHTML='<b>Active DR for this sight:</b> '+lat(own?la:st.drlat)+' &nbsp; '+\n"
"    lon(own?lo:st.drlon)+' &nbsp; <span class=\"sub\">('+\n"
"    (own?'this sight\\u2019s own DR':'from Setup')+'; live values, not examples)</span>';\n"
"}\n"
"/* Which sight is being edited, or null when entering a new one. */\n"
"let editIndex=null;\n"
"\n"
"const fnum=(id,dflt)=>{ const v=parseFloat($(id).value); return isFinite(v)?v:dflt; };\n"
"\n"
"function formSight(){\n"
"  const dparts=($('date').value||'').split(/[-/ ]/).map(Number);\n"
"  const tparts=($('time').value||'').split(/[: ]/).map(Number);\n"
"  return {\n"
"    body:$('body').value, star:$('star').value.trim(),\n"
"    y:dparts[0]||2026, mo:dparts[1]||1, d:dparts[2]||1,\n"
"    h:tparts[0]||0, mi:tparts[1]||0, s:tparts[2]||0,\n"
"    hs:(parseFloat($('hsd').value)||0)+(parseFloat($('hsm').value)||0)/60,\n"
"    ie:fnum('f_ie',0), iearc:$('f_iearc').value,\n"
"    horizon:$('f_horizon').value, he:fnum('f_he',0), heunit:$('f_heunit').value,\n"
"    limb:$('limb').value, temp:fnum('f_temp',10), press:fnum('f_press',1010),\n"
"    drlat:parsePos($('f_drlat').value), drlon:parsePos($('f_drlon').value),\n"
"    label:$('label').value.trim(),\n"
"    course:fnum('f_course',0), speed:fnum('f_speed',0),\n"
"    set:fnum('f_set',0), drift:fnum('f_drift',0)\n"
"  };\n"
"}\n"
"\n"
"/* Fill every field on the Sight tab from a stored sight, or from the Setup\n"
"   defaults when called with nothing (a fresh observation). */\n"
"function fillSight(s){\n"
"  const st=loadSetup();\n"
"  const src = s || {ie:st.ie,iearc:st.iearc,horizon:st.horizon,he:st.he,heunit:st.heunit,\n"
"                    limb:st.limb||'ll',temp:st.temp,press:st.press,\n"
"                    drlat:st.drlat,drlon:st.drlon,course:0,speed:0,set:0,drift:0};\n"
"  if(s){\n"
"    $('body').value=s.body; $('star').value=s.star||'';\n"
"    $('date').value=s.y+'-'+pad(s.mo,2)+'-'+pad(s.d,2);\n"
"    $('time').value=pad(s.h,2)+':'+pad(s.mi,2)+':'+pad(Math.round(s.s),2);\n"
"    const deg=Math.floor(s.hs), min=(s.hs-deg)*60;\n"
"    $('hsd').value=deg; $('hsm').value=min.toFixed(1);\n"
"    $('label').value=s.label||'';\n"
"  }\n"
"  $('f_ie').value=src.ie; $('f_iearc').value=src.iearc;\n"
"  $('f_horizon').value=src.horizon; $('f_he').value=src.he; $('f_heunit').value=src.heunit;\n"
"  $('limb').value=src.limb||'ll';\n"
"  $('f_temp').value=src.temp; $('f_press').value=src.press;\n"
"  $('f_drlat').value=src.drlat?lat(src.drlat):''; $('f_drlon').value=src.drlon?lon(src.drlon):'';\n"
"  $('f_course').value=src.course||''; $('f_speed').value=src.speed||'';\n"
"  $('f_set').value=src.set||''; $('f_drift').value=src.drift||'';\n"
"  $('starwrap').style.display=($('body').value==='star')?'':'none';\n"
"  $('limbwrap').style.display=(['sun','moon'].includes($('body').value))?'':'none';\n"
"}\n"
"\n"
"/* Open a stored sight for editing: every field, including the ones that\n"
"   normally come from Setup, so one change does not mean retyping the shot. */\n"
"function editSight(i){\n"
"  const arr=loadSights();\n"
"  if(i<0 || i>=arr.length) return;\n"
"  editIndex=i;\n"
"  fillSight(arr[i]);\n"
"  $('sightsettings').open=true;\n"
"  $('sightsettings').classList.add('editing');\n"
"  $('save').textContent='Update sight';\n"
"  $('cancel').style.display='';\n"
"  $('savemsg').textContent='Editing sight '+(i+1)+' of '+arr.length+'. Every field is shown.';\n"
"  show('sight');\n"
"  refresh();\n"
"}\n"
"\n"
"function endEdit(msg){\n"
"  editIndex=null;\n"
"  $('sightsettings').open=false;\n"
"  $('sightsettings').classList.remove('editing');\n"
"  $('save').textContent='Save to sights';\n"
"  $('cancel').style.display='none';\n"
"  $('savemsg').textContent=msg||'';\n"
"}\n"
"function query(s,i){\n"
"  const k=n=>(i===undefined?n:n+i);\n"
"  const p=new URLSearchParams();\n"
"  const add=(n,v)=>p.set(k(n),v);\n"
"  add('body',s.body); add('star',s.star||'');\n"
"  add('y',s.y); add('mo',s.mo); add('d',s.d); add('h',s.h); add('mi',s.mi); add('s',s.s);\n"
"  add('hs',s.hs); add('ie',s.ie); add('iearc',s.iearc); add('horizon',s.horizon);\n"
"  add('he',s.he); add('heunit',s.heunit); add('limb',s.limb);\n"
"  add('temp',s.temp); add('press',s.press); add('drlat',s.drlat); add('drlon',s.drlon);\n"
"  add('label',s.label||'');\n"
"  add('course',s.course||0); add('speed',s.speed||0);\n"
"  add('set',s.set||0); add('drift',s.drift||0);\n"
"  return p.toString();\n"
"}\n"
"\n"
"/* ---------- worked sight ---------- */\n"
"function row(k,formula,value,cls){\n"
"  return `<tr class=\"${cls||''}\"><td class=\"k\">${k}</td>\n"
"    <td class=\"f\">${formula||''}</td><td class=\"v\">${value||''}</td></tr>`;\n"
"}\n"
"function renderWorked(r){\n"
"  if(r.error) return `<h2>Worked sight</h2><p class=\"err\">${r.error}</p>`;\n"
"  const AH=r.artificial, moon=(r.body==='moon');\n"
"  let h='<h2>Hs to Ho</h2><table class=\"work\">';\n"
"  h+=row('Hs','sextant altitude',alt(r.hs));\n"
"  h+=row('IC',`${v('Hs')} ${r.ie_min?(r.ie_on_arc?'\\u2212':'+'):'\\u00b1'} ${num(Math.abs(r.ie_min),1)}\\u2032 &nbsp;<span class=\"sub\">index error ${r.ie_on_arc?'on':'off'} the arc</span>`,mins(r.ic_min));\n"
"  if(AH){\n"
"    h+=row('Ha',`${frac(v('Hs')+' + IC','2')}<span class=\"sub\">artificial horizon: the reading is a double altitude, and there is no dip</span>`,alt(r.ha));\n"
"  }else{\n"
"    h+=row('Dip',`${num(r.he_metres?1.76:0.97,2)}\\u2032 ${sqrt(num(r.he,1)+(r.he_metres?' m':' ft'))}`,mins(-r.dip_min));\n"
"    h+=row('Ha',`${v('Hs')} + IC \\u2212 dip`,alt(r.ha));\n"
"  }\n"
"  h+=row('R<sub>0</sub>',\n"
"    `${frac('0.0167\\u00b0','tan('+v('Ha')+' + '+frac('7.32',v('Ha')+' + 4.32')+')')}\n"
"     <span class=\"sub\">= 0.0167\\u00b0 / tan(${num(r.ha,2)}\\u00b0 + 7.32/(${num(r.ha,2)} + 4.32)) = ${num(r.r0_min,2)}\\u2032</span>`,\n"
"    mins(-r.r0_min));\n"
"  h+=row('f',\n"
"    `${frac('0.28 '+v('P'),v('T')+' + 273')}\n"
"     <span class=\"sub\">= 0.28 \\u00d7 ${num(r.press_mb,1)} mb / ${num(r.temp_c+273,1)} K</span>`,\n"
"    num(r.f,4));\n"
"  h+=row('R',`${v('f')} \\u00d7 R<sub>0</sub>`,mins(-r.r_min));\n"
"  if(r.used_sd){\n"
"    const lab=(r.limb>0?'lower':'upper')+' limb';\n"
"    h+=row('SD',\n"
"      moon ? `SD<span class=\"op\">\\u00b7</span>(1 + sin HP<span class=\"op\">\\u00b7</span>sin ${v('H')})\n"
"              <span class=\"sub\">${lab}: ${num(r.sd_raw_min,2)}\\u2032 augmented to ${num(Math.abs(r.sd_min),2)}\\u2032</span>`\n"
"           : `almanac semidiameter<span class=\"sub\">${lab}: ${num(r.sd_raw_min,2)}\\u2032</span>`,\n"
"      mins(r.sd_min));\n"
"  }\n"
"  if(r.used_par)\n"
"    h+=row('P<sub>a</sub>',\n"
"      `arcsin(sin HP<span class=\"op\">\\u00b7</span>cos ${v('H')})\n"
"       <span class=\"sub\">HP = ${num(r.hp_min,2)}\\u2032</span>`,\n"
"      mins(r.par_min));\n"
"  h+=row('Ho','observed altitude',alt(r.ho),'total');\n"
"  h+='</table>';\n"
"\n"
"  if(!r.has_dr){\n"
"    h+='<p class=\"hint\">Set a DR on the Setup tab to reduce this sight to a line of position.</p>';\n"
"    return h;\n"
"  }\n"
"\n"
"  /* almanac */\n"
"  h+='<h2 style=\"margin-top:1.2rem\">Almanac</h2><table class=\"work\">';\n"
"  if(r.is_star){\n"
"    h+=row('GHA \\u2648 '+pad(r.hour_h,2)+'h','hourly page',gha(r.gha_aries_hour));\n"
"    h+=row('Increment',`${num(r.frac_hour*60,2)} min \\u00d7 15\\u00b0 02.46\\u2032/h`,gha(r.inc_deg));\n"
"    h+=row('GHA \\u2648','',gha(r.gha_aries));\n"
"    h+=row('SHA',r.star,gha(r.sha_deg));\n"
"    h+=row('GHA','GHA \\u2648 + SHA',gha(r.gha));\n"
"    h+=row('Dec','',lat(r.dec));\n"
"  }else{\n"
"    const rate=moon?'14\\u00b0 19.0\\u2032/h':'15\\u00b0 00.0\\u2032/h';\n"
"    h+=row('GHA '+pad(r.hour_h,2)+'h','hourly page',gha(r.gha_hour));\n"
"    h+=row('Increment',`${num(r.frac_hour*60,2)} min \\u00d7 ${rate}`,gha(r.inc_deg));\n"
"    if(r.has_v) h+=row('v corr',`${v('v')} \\u00d7 ${num(r.frac_hour,4)} h &nbsp;<span class=\"sub\">v = ${mins(r.v_min)} per hour</span>`,mins(r.vcorr_min));\n"
"    h+=row('GHA','',gha(r.gha));\n"
"    h+=row('Dec '+pad(r.hour_h,2)+'h','hourly page',lat(r.dec_hour));\n"
"    h+=row('d corr',`${v('d')} \\u00d7 ${num(r.frac_hour,4)} h &nbsp;<span class=\"sub\">d = ${mins(r.d_min)} per hour, + when |Dec| grows</span>`,mins(r.dcorr_min));\n"
"    h+=row('Dec','',lat(r.dec));\n"
"    let dg=(r.gha_exact-r.gha)*60; while(dg>10800)dg-=21600; while(dg<-10800)dg+=21600;\n"
"    h+=row('check',`engine at the exact second<span class=\"sub\">Dec ${mins((r.dec_exact-r.dec)*60)}</span>`,mins(dg));\n"
"  }\n"
"  h+='</table>';\n"
"\n"
"  /* assumed position and HO 229 */\n"
"  h+='<h2 style=\"margin-top:1.2rem\">Assumed position</h2><table class=\"work\">';\n"
"  h+=row('a-Lat','DR latitude to the whole degree',lat(r.ap_lat));\n"
"  h+=row('a-Lon','minutes chosen for a whole-degree LHA',lon(r.ap_lon));\n"
"  h+=row('LHA','GHA + a-Lon',pad(r.lha,3)+'\\u00b0');\n"
"  h+='</table>';\n"
"\n"
"  h+=`<h2 style=\"margin-top:1.2rem\">HO 229 &nbsp;<span style=\"font-weight:400;text-transform:none;letter-spacing:0\">LHA ${pad(r.lha,3)}\\u00b0, Lat ${Math.abs(Math.round(r.ap_lat))}\\u00b0 ${r.ap_lat<0?'S':'N'}, Dec ${r.dec_deg_whole}\\u00b0 ${r.same_name?'same':'contrary'} name</span></h2><table class=\"work\">`;\n"
"  h+=row('Tab Hc','tabulated for the whole degree of Dec',alt(r.tab_hc_min/60));\n"
"  h+=row('d','change in Hc per degree of Dec',mins(r.d_tab_min));\n"
"  h+=row('Dec inc','',num(r.dec_inc_min,1)+'\\u2032');\n"
"  h+=row('d corr',`${frac(v('d')+' \\u00d7 Dec inc','60')}`,mins(r.dcorr229_min));\n"
"  if(Math.abs(r.secdiff_min)>=0.05) h+=row('2nd diff','second-difference residual',mins(r.secdiff_min));\n"
"  h+=row('Hc','',alt(r.hc_min/60));\n"
"  h+=row('Z',`arccos ${frac('sin Dec \\u2212 sin Lat<span class=\"op\">\\u00b7</span>sin '+v('Hc'),'cos Lat<span class=\"op\">\\u00b7</span>cos '+v('Hc'))}`,\n"
"        (r.ap_lat<0?'S':'N')+' '+num(r.z,1)+'\\u00b0 '+(r.lha>180?'E':'W'));\n"
"  h+=row('Zn','from Z by the LHA rule',pad(Math.round(r.zn),3)+'\\u00b0');\n"
"  h+='</table>';\n"
"\n"
"  h+='<h2 style=\"margin-top:1.2rem\">Line of position</h2><table class=\"work\">';\n"
"  h+=row('Ho','',alt(r.ho));\n"
"  h+=row('Hc','',alt(r.hc_min/60));\n"
"  h+=row('Intercept',`${v('a')} = Ho \\u2212 Hc &nbsp;<span class=\"sub\">${r.intercept_nm>=0?'Ho greater: toward':'Ho less: away'}</span>`,\n"
"        num(Math.abs(r.intercept_nm),1)+' NM '+(r.intercept_nm>=0?'T':'A'),'total');\n"
"  h+='</table>';\n"
"  return h;\n"
"}\n"
"\n"
"let reduceTimer=null;\n"
"function refresh(){\n"
"  clearTimeout(reduceTimer);\n"
"  reduceTimer=setTimeout(async ()=>{\n"
"    const s=formSight();\n"
"    if(!(s.hs>0)){ $('worked').innerHTML='<h2>Worked sight</h2><p class=\"hint\">Enter Hs to see the worked sight.</p>'; return; }\n"
"    try{\n"
"      const r=await (await fetch('/api/reduce?'+query(s))).json();\n"
"      $('worked').innerHTML=renderWorked(r);\n"
"    }catch(e){ $('worked').innerHTML='<h2>Worked sight</h2><p class=\"err\">server not reachable</p>'; }\n"
"  },120);\n"
"}\n"
"\n"
"/* ---------- star matching ---------- */\n"
"async function starMatch(){\n"
"  const q=$('star').value.trim();\n"
"  const box=$('starmatches');\n"
"  box.innerHTML='';\n"
"  if(!q) return;\n"
"  const r=await (await fetch('/api/stars?q='+encodeURIComponent(q))).json();\n"
"  if(r.count===1 && r.matches[0].toLowerCase()===q.toLowerCase()) return;\n"
"  if(r.count>9){ box.innerHTML='<span class=\"hint\">'+r.count+' stars match; type another letter</span>'; return; }\n"
"  r.matches.forEach(n=>{\n"
"    const b=document.createElement('button');\n"
"    b.textContent=n;\n"
"    b.onclick=()=>{ $('star').value=n; box.innerHTML=''; refresh(); };\n"
"    box.appendChild(b);\n"
"  });\n"
"}\n"
"\n"
"\n"
"/* ---------- almanac ---------- */\n"
"function almanacQuery(){\n"
"  const dp=($('a_date').value||'').split(/[-/ ]/).map(Number);\n"
"  const tp=($('a_time').value||'').split(/[: ]/).map(Number);\n"
"  const p=new URLSearchParams();\n"
"  p.set('body',$('a_body').value);\n"
"  p.set('star',$('a_star').value.trim());\n"
"  p.set('y',dp[0]||2026); p.set('mo',dp[1]||1); p.set('d',dp[2]||1);\n"
"  p.set('h',tp[0]||0); p.set('mi',tp[1]||0); p.set('s',tp[2]||0);\n"
"  const setup=loadSetup();\n"
"  p.set('drlat',setup.drlat); p.set('drlon',setup.drlon);\n"
"  return p.toString();\n"
"}\n"
"let almanacRequest=0;\n"
"function paperTable(p,r){\n"
"  let h='<h2>Celestial Navigation Data</h2><div class=\"papercontext\">';\n"
"  h+=`${r.y}-${pad(r.mo,2)}-${pad(r.d,2)} ${pad(r.h,2)}:${pad(r.mi,2)}:${pad(Math.round(r.s),2)} UTC<br>`;\n"
"  h+=`Delta T = ${num(p.delta_t,1)} seconds (DUT1=0 assumed)<br>`;\n"
"  h+=`For assumed location: ${lat(p.drlat)} &nbsp; ${lon(p.drlon)} <span class=\"hint\">from Setup</span></div>`;\n"
"  h+='<div class=\"paperscroll\"><table class=\"paper\"><thead><tr><th colspan=\"5\">Almanac Data</th>';\n"
"  h+='<th class=\"corrections\" colspan=\"4\">Altitude Corrections</th></tr><tr>';\n"
"  h+='<th>Object</th><th>GHA<br>° ′</th><th>Dec<br>° ′</th><th>Hc<br>° ′</th><th>Zn<br>°</th>';\n"
"  h+='<th class=\"corrections\">Refr<br>′</th><th>SD<br>′</th><th>PA<br>′</th><th>Sum<br>′</th></tr></thead><tbody>';\n"
"  for(const q of p.rows){\n"
"    h+=`<tr><td>${q.name}</td><td>${gha(q.gha)}</td>`;\n"
"    if(q.is_aries){ h+='<td></td><td></td><td></td><td class=\"corrections\"></td><td></td><td></td><td></td>'; }\n"
"    else{\n"
"      h+=`<td>${lat(q.dec)}</td><td>${q.hc>=0?'+':''}${alt(q.hc)}</td><td>${q.have_azimuth?num(q.zn,1):'—'}</td>`;\n"
"      h+=q.have_corrections\n"
"        ? `<td class=\"corrections\">${num(q.refr_min,1)}</td><td>${num(q.sd_min,1)}</td><td>${num(q.par_min,1)}</td><td>${num(q.sum_min,1)}</td>`\n"
"        : '<td class=\"corrections\">—</td><td>—</td><td>—</td><td>—</td>';\n"
"    }\n"
"    h+='</tr>';\n"
"  }\n"
"  h+='</tbody></table></div><div class=\"hint\">Corrections estimated at the DR: standard atmosphere, Sun/Moon lower limb. '\n"
"    +'Sum = Refr + SD + PA. Apply dip and index error separately. Corrections are omitted below −0.5°.</div>';\n"
"  return h;\n"
"}\n"
"async function refreshAlmanac(){\n"
"  const box=$('almanacout'), request=++almanacRequest, qs=almanacQuery();\n"
"  try{\n"
"    const [r,p]=await Promise.all([\n"
"      fetch('/api/almanac?'+qs).then(x=>x.json()),\n"
"      fetch('/api/paper?'+qs).then(x=>x.json())]);\n"
"    if(request!==almanacRequest) return;\n"
"    if(r.error){ box.innerHTML='<h2>Almanac result</h2><p class=\"err\">'+r.error+'</p>'; return; }\n"
"    let h=p.error ? '<h2>Celestial Navigation Data</h2><p class=\"err\">'+p.error+'</p>' : paperTable(p,r);\n"
"    h+='<details class=\"subcard\"><summary>Additional almanac data</summary><table class=\"work\">';\n"
"    h+=row('Body','',r.name||'');\n"
"    h+=row('UTC','',`${r.y}-${pad(r.mo,2)}-${pad(r.d,2)} ${pad(r.h,2)}:${pad(r.mi,2)}:${pad(Math.round(r.s),2)}`);\n"
"    if(r.is_star){\n"
"      h+=row('GHA','Greenwich hour angle',gha2(r.gha));\n"
"      h+=row('SHA','sidereal hour angle',gha2(r.sha));\n"
"      h+=row('Dec','apparent declination',lat2(r.dec));\n"
"      h+=row('RA','apparent right ascension',radms(r.ra));\n"
"      h+=row('Mag','visual magnitude',num(r.mag,2));\n"
"    }else{\n"
"      h+=row('GHA','Greenwich hour angle',gha2(r.gha));\n"
"      if(r.body!=='aries') h+=row('Dec','apparent declination',lat2(r.dec));\n"
"      if(r.body!=='aries') h+=row('RA','apparent right ascension',radms(r.ra));\n"
"      if(r.hp_min>0.0005) h+=row('HP','horizontal parallax',num(r.hp_min,2)+'\\u2032');\n"
"      if(r.sd_min>0.0005) h+=row('SD','semidiameter',num(r.sd_min,2)+'\\u2032');\n"
"    }\n"
"    h+='</table></details>';\n"
"    box.innerHTML=h;\n"
"  }catch(e){\n"
"    if(request!==almanacRequest) return;\n"
"    box.innerHTML='<h2>Almanac result</h2><p class=\"err\">Could not reach the almanac endpoint.</p>';\n"
"  }\n"
"}\n"
"function setAlmanacNow(){\n"
"  const d=new Date();\n"
"  $('a_date').value=d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1,2)+'-'+pad(d.getUTCDate(),2);\n"
"  $('a_time').value=pad(d.getUTCHours(),2)+':'+pad(d.getUTCMinutes(),2)+':'+pad(d.getUTCSeconds(),2);\n"
"}\n"
"\n"
"async function dailyAlmanac(style){\n"
"  const request=++almanacRequest;\n"
"  const dp=($('a_date').value||'').split(/[-/ ]/).map(Number);\n"
"  const p=new URLSearchParams();\n"
"  p.set('style',style); p.set('y',dp[0]||2026); p.set('mo',dp[1]||1); p.set('d',dp[2]||1);\n"
"  const box=$('almanacout');\n"
"  box.innerHTML='<h2>Almanac table</h2><div class=\"hint\">Building table&hellip;</div>';\n"
"  try{\n"
"    const r=await fetch('/api/daily?'+p.toString());\n"
"    const html=await r.text();\n"
"    if(request!==almanacRequest) return;\n"
"    const q='y='+(dp[0]||2026)+'&mo='+(dp[1]||1)+'&d='+(dp[2]||1);\n"
"    box.innerHTML=html\n"
"      +'<div class=\"printlink\"><a href=\"/daily/'+(style==='air'?'air':'naval')+'?'+q\n"
"      +'\" target=\"_blank\" rel=\"noopener\">Open a printable page in a new tab</a></div>';\n"
"  }catch(e){\n"
"    if(request!==almanacRequest) return;\n"
"    box.innerHTML='<h2>Almanac table</h2><p class=\"err\">Could not reach the daily-table endpoint.</p>';\n"
"  }\n"
"}\n"
"\n"
"/* ---------- stored sights ---------- */\n"
"let listRequest=0;\n"
"async function renderList(){\n"
"  const request=++listRequest, arr=loadSights(), tb=$('listbody');\n"
"  tb.innerHTML='';\n"
"  if(!arr.length){ tb.innerHTML='<tr><td colspan=\"8\" class=\"hint\">No sights yet.</td></tr>'; return; }\n"
"  for(let i=0;i<arr.length;i++){\n"
"    const s=arr[i];\n"
"    let r={};\n"
"    try{ r=await (await fetch('/api/reduce?'+query(s))).json(); }catch(e){}\n"
"    /* A newer refresh owns the table, even if this response arrived last. */\n"
"    if(request!==listRequest) return;\n"
"    const tr=document.createElement('tr');\n"
"    if(s.sel) tr.className='sel';\n"
"    tr.innerHTML=`<td><input type=\"checkbox\" ${s.sel?'checked':''}></td>\n"
"      <td>${s.body==='star'?s.star:s.body}</td>\n"
"      <td>${s.y}-${pad(s.mo,2)}-${pad(s.d,2)} ${pad(s.h,2)}:${pad(s.mi,2)}:${pad(Math.round(s.s),2)}</td>\n"
"      <td>${r.ok?alt(r.ho):'\\u2014'}</td>\n"
"      <td>${r.ok&&r.has_dr?num(Math.abs(r.intercept_nm),1)+' '+(r.intercept_nm>=0?'T':'A'):'\\u2014'}</td>\n"
"      <td>${r.ok&&r.has_dr?pad(Math.round(r.zn),3):'\\u2014'}</td>\n"
"      <td>${s.label||''}</td>\n"
"      <td class=\"rowacts\"><button class=\"ghost edit\" style=\"padding:.15rem .5rem\">edit</button>\n"
"        <button class=\"ghost del\" style=\"padding:.15rem .5rem\">delete</button></td>`;\n"
"    tr.querySelector('input').onchange=e=>{ arr[i].sel=e.target.checked; saveSights(arr); renderList(); renderMotion(); };\n"
"    tr.querySelector('button.edit').onclick=()=>editSight(i);\n"
"    tr.querySelector('button.del').onclick=()=>{\n"
"      if(editIndex===i) endEdit('');\n"
"      arr.splice(i,1); saveSights(arr); renderList(); renderMotion(); };\n"
"    tb.appendChild(tr);\n"
"  }\n"
"}\n"
"\n"
"function renderMotion(){\n"
"  const arr=loadSights().map((s,i)=>({s,i})).filter(o=>o.s.sel);\n"
"  const box=$('motionrows');\n"
"  if(!arr.length){ box.innerHTML='<div class=\"hint\">No sights selected.</div>'; return; }\n"
"  box.innerHTML='';\n"
"  arr.forEach(({s,i})=>{\n"
"    const d=document.createElement('div');\n"
"    d.style.marginTop='.7rem';\n"
"    d.innerHTML=`<label>${s.body==='star'?s.star:s.body} ${pad(s.h,2)}:${pad(s.mi,2)} ${s.label||''}</label>\n"
"      <div class=\"row\">\n"
"        <input placeholder=\"course\" value=\"${s.course||''}\">\n"
"        <input placeholder=\"speed kt\" value=\"${s.speed||''}\">\n"
"        <input placeholder=\"set\" value=\"${s.set||''}\">\n"
"        <input placeholder=\"drift kt\" value=\"${s.drift||''}\">\n"
"      </div>`;\n"
"    const ins=d.querySelectorAll('input');\n"
"    ins.forEach((inp,k)=>{\n"
"      inp.onchange=()=>{\n"
"        const a=loadSights();\n"
"        const val=parseFloat(inp.value)||0;\n"
"        if(k===0)a[i].course=val; else if(k===1)a[i].speed=val;\n"
"        else if(k===2)a[i].set=val; else a[i].drift=val;\n"
"        saveSights(a);\n"
"      };\n"
"    });\n"
"    box.appendChild(d);\n"
"  });\n"
"}\n"
"\n"
"/* ---- universal plotting sheet ---------------------------------------\n"
"   Drawn the way a fix is plotted on paper under HO 229: every sight\n"
"   keeps its own assumed position, the azimuth is laid off from that AP,\n"
"   the intercept is stepped toward the body or away from it, and the LOP\n"
"   is drawn square to the azimuth at that point.  Meridians are spaced\n"
"   the parallel spacing times cos(latitude), which is the whole trick of\n"
"   a universal sheet.  Scale and grid step follow the spread of the\n"
"   sights, so a tight fix and a scattered running fix both read well. */\n"
"function plotSheetGeometry(r){\n"
"  if(!r || !Array.isArray(r.lops) || r.lops.length<2) return null;\n"
"  const lat0=r.lat, lon0=r.lon;\n"
"  if(!Number.isFinite(lat0) || !Number.isFinite(lon0) || Math.abs(lat0)>90) return null;\n"
"  if(r.lops.some(l=>![l.ap_lat,l.ap_lon,l.zn,l.intercept_nm,\n"
"      l.advanced_nm??0,l.advanced_brg??0].every(Number.isFinite))) return null;\n"
"  /* Match navsight_fix's plane, including its mean assumed latitude.\n"
"     Recentring on the fix must not change the longitude scale. */\n"
"  const gridLat=r.lops.reduce((sum,l)=>sum+l.ap_lat,0)/r.lops.length;\n"
"  const CL=Math.cos(gridLat*Math.PI/180);\n"
"  if(CL<1e-6) return null;\n"
"  const toNM=(la,lo)=>({e:(lo-lon0)*60*CL, n:(la-lat0)*60});\n"
"\n"
"  /* every LOP, in nautical miles from the fix */\n"
"  const L=r.lops.map(l=>{\n"
"    const a0=toNM(l.ap_lat,l.ap_lon);\n"
"    let ap=a0;\n"
"    const adv=l.advanced_nm||0;\n"
"    if(adv>0){\n"
"      const b=(l.advanced_brg||0)*Math.PI/180;\n"
"      ap={e:a0.e+adv*Math.sin(b), n:a0.n+adv*Math.cos(b)};\n"
"    }\n"
"    const z=l.zn*Math.PI/180;\n"
"    const u={e:Math.sin(z), n:Math.cos(z)};          /* toward the body */\n"
"    const t={e:ap.e+l.intercept_nm*u.e, n:ap.n+l.intercept_nm*u.n};\n"
"    return {name:l.name, zn:l.zn, a:l.intercept_nm, adv:adv,\n"
"            ap0:a0, ap:ap, u:u, t:t,\n"
"            p:{e:Math.cos(z), n:-Math.sin(z)}};      /* along the LOP */\n"
"  });\n"
"  return {lat0,lon0,gridLat,CL,L};\n"
"}\n"
"\n"
"function plotSheet(r){\n"
"  if(!r || !Array.isArray(r.lops) || r.lops.length<2) return '';\n"
"  const geometry=plotSheetGeometry(r);\n"
"  if(!geometry) return '<p class=\"hint\">The plotting sheet needs finite coordinates away from the poles.</p>';\n"
"  const {lat0,lon0,gridLat,CL,L}=geometry;\n"
"  const W=760, H=772, PAD=46, CAP=34, STRIP=150;\n"
"  const niceInterval=target=>{\n"
"    const decade=Math.pow(10,Math.floor(Math.log10(target)));\n"
"    return [1,2,5,10].map(x=>x*decade).find(x=>x>=target);\n"
"  };\n"
"\n"
"  const pts=[{e:0,n:0}];\n"
"  L.forEach(x=>{ pts.push(x.ap0); pts.push(x.ap); pts.push(x.t); });\n"
"  const es=pts.map(p=>p.e), ns=pts.map(p=>p.n);\n"
"  const ce=(Math.min(...es)+Math.max(...es))/2, cn=(Math.min(...ns)+Math.max(...ns))/2;\n"
"  const span=Math.max(Math.max(...es)-Math.min(...es),\n"
"                      Math.max(...ns)-Math.min(...ns), 1.5)*1.6;\n"
"\n"
"  const pw=W-2*PAD, ph=H-2*PAD-CAP-STRIP;\n"
"  const s=Math.min(pw,ph)/span;                      /* px per nautical mile */\n"
"  const pcx=PAD+pw/2, pcy=PAD+ph/2;\n"
"  const X=p=>pcx+(p.e-ce)*s, Y=p=>pcy-(p.n-cn)*s;\n"
"  const XY=p=>X(p).toFixed(1)+','+Y(p).toFixed(1);\n"
"\n"
"  const INK='#1f2a30', MUT='#5a6b74', GRID='#dde6ec', GRIDJ='#a8bcc9',\n"
"        ROSE='#4a5a66', FIXC='#8b1a1a';\n"
"  const COL=['#b4472e','#2d6a4f','#3a5a8c','#8a6d1f','#6b3a7a','#2e6f74'];\n"
"  const e=[];                                        /* svg pieces */\n"
"  const esc=t=>String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');\n"
"  const T=(x,y,t,o)=>{ o=o||{};\n"
"    e.push('<text x=\"'+x.toFixed(1)+'\" y=\"'+y.toFixed(1)+'\" font-size=\"'+(o.size||11)+\n"
"      '\" fill=\"'+(o.fill||INK)+'\" text-anchor=\"'+(o.anchor||'start')+\n"
"      '\" font-family=\"'+(o.mono?'ui-monospace,Menlo,Consolas,monospace':'system-ui,sans-serif')+\n"
"      '\" font-weight=\"'+(o.weight||'normal')+'\"'+(o.style?' font-style=\"'+o.style+'\"':'')+\n"
"      '>'+esc(t)+'</text>'); };\n"
"  const HALO=(x,y,t,o)=>{ o=o||{};\n"
"    e.push('<text x=\"'+x.toFixed(1)+'\" y=\"'+y.toFixed(1)+'\" font-size=\"'+(o.size||11)+\n"
"      '\" text-anchor=\"'+(o.anchor||'start')+'\" font-family=\"'+\n"
"      (o.mono?'ui-monospace,Menlo,Consolas,monospace':'system-ui,sans-serif')+\n"
"      '\" font-weight=\"'+(o.weight||'normal')+\n"
"      '\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"3.5\" stroke-linejoin=\"round\">'+esc(t)+'</text>');\n"
"    T(x,y,t,o); };\n"
"\n"
"  e.push('<rect x=\"'+PAD+'\" y=\"'+PAD+'\" width=\"'+pw+'\" height=\"'+ph+\n"
"         '\" fill=\"#ffffff\" stroke=\"'+ROSE+'\" stroke-width=\"1.2\"/>');\n"
"  e.push('<clipPath id=\"psclip\"><rect x=\"'+PAD+'\" y=\"'+PAD+'\" width=\"'+pw+'\" height=\"'+ph+'\"/></clipPath>');\n"
"  e.push('<g clip-path=\"url(#psclip)\">');\n"
"\n"
"  /* graticule: pick a step that gives a readable number of lines */\n"
"  const step=[0.5,1,2,5,10,15,30,60].find(c=>span/c<=11)||niceInterval(span/11);\n"
"  const dec=step<1?1:0;\n"
"  const dm=(v,pos,neg)=>{ const h=v<0?neg:pos, a=Math.abs(v), d=Math.floor(a/60),\n"
"                          m=a-d*60; return h+' '+d+'° '+(m<10?'0':'')+m.toFixed(dec)+\"'\"; };\n"
"  const halfN=(ph/2)/s, halfE=(pw/2)/s;\n"
"  /* Widen longitude intervals near the poles instead of generating\n"
"     thousands of tightly packed meridians. */\n"
"  const lonStep=Math.max(step,niceInterval(2*halfE/CL/20));\n"
"  const latC=lat0*60+cn, lonC=lon0*60+ce/CL;\n"
"  for(let k=Math.floor((latC-halfN)/step); k<=Math.ceil((latC+halfN)/step); k++){\n"
"    const v=k*step, y=pcy-(v-latC)*s;\n"
"    if(y<PAD||y>PAD+ph) continue;\n"
"    e.push('<line x1=\"'+PAD+'\" y1=\"'+y.toFixed(1)+'\" x2=\"'+(PAD+pw)+'\" y2=\"'+y.toFixed(1)+\n"
"           '\" stroke=\"'+GRIDJ+'\" stroke-width=\"0.8\"/>');\n"
"    T(PAD+4,y-4,dm(v,'N','S'),{size:9,fill:MUT,mono:1});\n"
"  }\n"
"  for(let k=Math.floor((lonC-halfE/CL)/lonStep); k<=Math.ceil((lonC+halfE/CL)/lonStep); k++){\n"
"    const v=k*lonStep, x=pcx+((v-lonC)*CL)*s;\n"
"    if(x<PAD||x>PAD+pw) continue;\n"
"    e.push('<line x1=\"'+x.toFixed(1)+'\" y1=\"'+PAD+'\" x2=\"'+x.toFixed(1)+'\" y2=\"'+(PAD+ph)+\n"
"           '\" stroke=\"'+GRIDJ+'\" stroke-width=\"0.8\"/>');\n"
"    if(x < PAD+pw-62) T(x+3,PAD+ph-5,dm(v,'E','W'),{size:9,fill:MUT,mono:1});\n"
"  }\n"
"\n"
"  /* compass rose, centred on the sheet */\n"
"  const RR=Math.min(pw,ph)*0.40;\n"
"  e.push('<circle cx=\"'+pcx+'\" cy=\"'+pcy+'\" r=\"'+RR.toFixed(1)+\n"
"         '\" fill=\"none\" stroke=\"'+ROSE+'\" stroke-width=\"1\" opacity=\"0.8\"/>');\n"
"  for(let d=0;d<360;d+=5){\n"
"    const a=d*Math.PI/180, lg=(d%10===0), r1=RR-(lg?11:6);\n"
"    e.push('<line x1=\"'+(pcx+Math.sin(a)*r1).toFixed(1)+'\" y1=\"'+(pcy-Math.cos(a)*r1).toFixed(1)+\n"
"           '\" x2=\"'+(pcx+Math.sin(a)*RR).toFixed(1)+'\" y2=\"'+(pcy-Math.cos(a)*RR).toFixed(1)+\n"
"           '\" stroke=\"'+ROSE+'\" stroke-width=\"'+(lg?0.8:0.4)+'\" opacity=\"0.75\"/>');\n"
"    if(d%30===0){ const rl=RR-20;\n"
"      T(pcx+Math.sin(a)*rl, pcy-Math.cos(a)*rl+3,\n"
"        (d<100?(d<10?'00':'0'):'')+d, {size:8.5,fill:ROSE,anchor:'middle',mono:1}); }\n"
"  }\n"
"\n"
"  /* each line of position, from its own assumed position */\n"
"  const LL=Math.max(span*0.42, 1.2);\n"
"  L.forEach((x,i)=>{\n"
"    const c=COL[i%COL.length];\n"
"    if(x.adv>0)\n"
"      e.push('<line x1=\"'+X(x.ap0).toFixed(1)+'\" y1=\"'+Y(x.ap0).toFixed(1)+\n"
"             '\" x2=\"'+X(x.ap).toFixed(1)+'\" y2=\"'+Y(x.ap).toFixed(1)+\n"
"             '\" stroke=\"'+c+'\" stroke-width=\"1.2\" stroke-dasharray=\"2 3\" opacity=\"0.85\"/>');\n"
"    const far={e:x.ap.e+x.u.e*LL*0.95, n:x.ap.n+x.u.n*LL*0.95};\n"
"    e.push('<line x1=\"'+X(x.ap).toFixed(1)+'\" y1=\"'+Y(x.ap).toFixed(1)+'\" x2=\"'+X(far).toFixed(1)+\n"
"           '\" y2=\"'+Y(far).toFixed(1)+'\" stroke=\"'+c+'\" stroke-width=\"0.9\" stroke-dasharray=\"6 4\" opacity=\"0.75\"/>');\n"
"    e.push('<line x1=\"'+X(x.ap).toFixed(1)+'\" y1=\"'+Y(x.ap).toFixed(1)+'\" x2=\"'+X(x.t).toFixed(1)+\n"
"           '\" y2=\"'+Y(x.t).toFixed(1)+'\" stroke=\"'+c+'\" stroke-width=\"3\" marker-end=\"url(#psa'+i+')\"/>');\n"
"    const l1={e:x.t.e+x.p.e*LL, n:x.t.n+x.p.n*LL}, l2={e:x.t.e-x.p.e*LL, n:x.t.n-x.p.n*LL};\n"
"    e.push('<line x1=\"'+X(l1).toFixed(1)+'\" y1=\"'+Y(l1).toFixed(1)+'\" x2=\"'+X(l2).toFixed(1)+\n"
"           '\" y2=\"'+Y(l2).toFixed(1)+'\" stroke=\"'+c+'\" stroke-width=\"2.2\"/>');\n"
"    e.push('<path d=\"M '+(X(x.ap)).toFixed(1)+' '+(Y(x.ap)-5).toFixed(1)+' L '+\n"
"           (X(x.ap)+4.5).toFixed(1)+' '+(Y(x.ap)+3).toFixed(1)+' L '+\n"
"           (X(x.ap)-4.5).toFixed(1)+' '+(Y(x.ap)+3).toFixed(1)+' Z\" fill=\"none\" stroke=\"'+c+'\" stroke-width=\"1.4\"/>');\n"
"    HALO(X(x.ap)+7, Y(x.ap)+12, 'AP '+(i+1), {size:9.5,fill:c,mono:1,weight:'bold'});\n"
"    /* name the end of the LOP that falls farther from the fix, so the\n"
"       label never lands on the fix symbol */\n"
"    const lpA={e:x.t.e+x.p.e*LL*0.72, n:x.t.n+x.p.n*LL*0.72},\n"
"          lpB={e:x.t.e-x.p.e*LL*0.72, n:x.t.n-x.p.n*LL*0.72};\n"
"    const lp=(lpA.e*lpA.e+lpA.n*lpA.n)>=(lpB.e*lpB.e+lpB.n*lpB.n)?lpA:lpB;\n"
"    HALO(X(lp), Y(lp)-6, x.name, {size:10,fill:c,anchor:'middle',style:'italic'});\n"
"    const mid={e:x.ap.e+x.u.e*x.a*0.5+x.p.e*0.30*span*0.1,\n"
"               n:x.ap.n+x.u.n*x.a*0.5+x.p.n*0.30*span*0.1};\n"
"    HALO(X(mid), Y(mid), Math.abs(x.a).toFixed(1)+\"' \"+(x.a>=0?'T':'A'),\n"
"         {size:9.5,fill:c,anchor:'middle',mono:1,weight:'bold'});\n"
"  });\n"
"\n"
"  /* cocked hat, when three lines bound one */\n"
"  let hat=null;\n"
"  if(L.length===3){\n"
"    const ix=(A,B)=>{ const d=A.u.e*B.u.n-A.u.n*B.u.e; if(Math.abs(d)<1e-9) return null;\n"
"      const a1=A.t.e*A.u.e+A.t.n*A.u.n, a2=B.t.e*B.u.e+B.t.n*B.u.n;\n"
"      return {e:(a1*B.u.n-A.u.n*a2)/d, n:(A.u.e*a2-a1*B.u.e)/d}; };\n"
"    const v=[ix(L[0],L[1]),ix(L[1],L[2]),ix(L[2],L[0])].filter(Boolean);\n"
"    if(v.length===3){\n"
"      hat=v;\n"
"      e.push('<polygon points=\"'+v.map(XY).join(' ')+'\" fill=\"'+FIXC+\n"
"             '\" fill-opacity=\"0.12\" stroke=\"'+FIXC+'\" stroke-width=\"0.9\"/>');\n"
"    }\n"
"  }\n"
"\n"
"  /* the fix */\n"
"  const F={e:0,n:0};\n"
"  e.push('<circle cx=\"'+X(F).toFixed(1)+'\" cy=\"'+Y(F).toFixed(1)+'\" r=\"5.5\" fill=\"none\" stroke=\"'+\n"
"         FIXC+'\" stroke-width=\"1.8\"/>');\n"
"  e.push('<circle cx=\"'+X(F).toFixed(1)+'\" cy=\"'+Y(F).toFixed(1)+'\" r=\"1.6\" fill=\"'+FIXC+'\"/>');\n"
"  HALO(X(F)+10, Y(F)-7, 'FIX', {size:11,fill:FIXC,mono:1,weight:'bold'});\n"
"  e.push('</g>');\n"
"\n"
"  /* scale bar */\n"
"  const sb=niceInterval(75/s);\n"
"  const bx=PAD+10, by=PAD+ph-30, bw=sb*s;\n"
"  e.push('<rect x=\"'+(bx-5)+'\" y=\"'+(by-19)+'\" width=\"'+(bw+10)+'\" height=\"26\" fill=\"#ffffff\" fill-opacity=\"0.9\" stroke=\"'+GRID+'\" stroke-width=\"0.6\"/>');\n"
"  e.push('<rect x=\"'+bx+'\" y=\"'+(by-11)+'\" width=\"'+(bw/2).toFixed(1)+'\" height=\"5\" fill=\"'+INK+'\"/>');\n"
"  e.push('<rect x=\"'+(bx+bw/2).toFixed(1)+'\" y=\"'+(by-11)+'\" width=\"'+(bw/2).toFixed(1)+'\" height=\"5\" fill=\"#ffffff\" stroke=\"'+INK+'\" stroke-width=\"0.6\"/>');\n"
"  T(bx+bw/2, by+2, sb+' NM', {size:9,fill:MUT,anchor:'middle',mono:1});\n"
"\n"
"  const defs=L.map((x,i)=>'<marker id=\"psa'+i+'\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" '+\n"
"    'markerWidth=\"5.5\" markerHeight=\"5.5\" orient=\"auto-start-reverse\">'+\n"
"    '<path d=\"M 0 0 L 10 5 L 0 10 z\" fill=\"'+COL[i%COL.length]+'\"/></marker>').join('');\n"
"\n"
"  T(PAD, PAD-14, 'UNIVERSAL PLOTTING SHEET', {size:11,fill:INK,weight:'bold'});\n"
"  T(PAD+pw, PAD-14, 'each sight from its own HO 229 assumed position',\n"
"    {size:10,fill:MUT,anchor:'end',style:'italic'});\n"
"  /* The cocked hat, enlarged.  At sheet scale three good lines cross in\n"
"     something smaller than the fix symbol, which hides the one thing a\n"
"     student needs to see: that they do not meet in a point. */\n"
"  const sy=PAD+ph+16;\n"
"  if(hat){\n"
"    const bw=196, bh=STRIP-26, bx=W-PAD-bw, by=sy;\n"
"    const he2=hat.map(p=>p.e), hn2=hat.map(p=>p.n);\n"
"    const hce=(Math.min(...he2)+Math.max(...he2))/2, hcn=(Math.min(...hn2)+Math.max(...hn2))/2;\n"
"    const hspan=Math.max(Math.max(...he2)-Math.min(...he2),\n"
"                         Math.max(...hn2)-Math.min(...hn2), 0.02)*2.3;\n"
"    const hs2=Math.min(bw-26,bh-34)/hspan;\n"
"    const hx=bx+bw/2, hy=by+bh/2+7;\n"
"    const HX=p=>hx+(p.e-hce)*hs2, HY=p=>hy-(p.n-hcn)*hs2;\n"
"    e.push('<rect x=\"'+bx+'\" y=\"'+by+'\" width=\"'+bw+'\" height=\"'+bh+\n"
"           '\" fill=\"#ffffff\" stroke=\"'+GRIDJ+'\" stroke-width=\"0.8\"/>');\n"
"    e.push('<clipPath id=\"pshat\"><rect x=\"'+bx+'\" y=\"'+by+'\" width=\"'+bw+'\" height=\"'+bh+'\"/></clipPath>');\n"
"    e.push('<g clip-path=\"url(#pshat)\">');\n"
"    L.forEach((x,i)=>{\n"
"      const c=COL[i%COL.length];\n"
"      const ai=x.t.e*x.u.e+x.t.n*x.u.n;\n"
"      const tsc=ai-(hce*x.u.e+hcn*x.u.n);\n"
"      const fe=hce+tsc*x.u.e, fn=hcn+tsc*x.u.n;\n"
"      const q1={e:fe+x.p.e*hspan, n:fn+x.p.n*hspan}, q2={e:fe-x.p.e*hspan, n:fn-x.p.n*hspan};\n"
"      e.push('<line x1=\"'+HX(q1).toFixed(1)+'\" y1=\"'+HY(q1).toFixed(1)+'\" x2=\"'+HX(q2).toFixed(1)+\n"
"             '\" y2=\"'+HY(q2).toFixed(1)+'\" stroke=\"'+c+'\" stroke-width=\"1.8\"/>');\n"
"    });\n"
"    e.push('<polygon points=\"'+hat.map(p=>HX(p).toFixed(1)+','+HY(p).toFixed(1)).join(' ')+\n"
"           '\" fill=\"'+FIXC+'\" fill-opacity=\"0.15\" stroke=\"'+FIXC+'\" stroke-width=\"1.1\"/>');\n"
"    e.push('<circle cx=\"'+HX(F).toFixed(1)+'\" cy=\"'+HY(F).toFixed(1)+'\" r=\"4.5\" fill=\"none\" stroke=\"'+\n"
"           FIXC+'\" stroke-width=\"1.6\"/>');\n"
"    e.push('<circle cx=\"'+HX(F).toFixed(1)+'\" cy=\"'+HY(F).toFixed(1)+'\" r=\"1.4\" fill=\"'+FIXC+'\"/>');\n"
"    e.push('</g>');\n"
"    T(bx+7, by+14, 'COCKED HAT \\u00d7'+Number((hs2/s).toPrecision(2)),\n"
"      {size:9,fill:MUT,mono:1,weight:'bold'});\n"
"  }\n"
"\n"
"  ['Longitude scale uses cos '+Math.abs(gridLat).toFixed(1)+'\\u00b0 = '+CL.toFixed(3)+'.',\n"
"   'Grid intervals: latitude '+step+\"', longitude \"+lonStep+\"'.\",\n"
"   '',\n"
"   'Every sight keeps its own HO 229 assumed position. The intercept',\n"
"   'is stepped toward the body when Ho is the greater and away when',\n"
"   'it is the less, then the LOP is drawn square to the azimuth.'\n"
"  ].forEach((t,i)=>{ if(t) T(PAD, sy+14+i*15, t, {size:9.5,fill:MUT}); });\n"
"\n"
"  return '<svg role=\"img\" aria-label=\"Celestial fix plotting sheet\" viewBox=\"0 0 '+W+' '+H+'\" width=\"100%\" style=\"max-width:'+W+\n"
"         'px;display:block;margin:1rem auto 0\" xmlns=\"http://www.w3.org/2000/svg\">'+\n"
"         '<defs>'+defs+'</defs>'+e.join('')+'</svg>';\n"
"}\n"
"\n"
"async function doFix(){\n"
"  const sel=loadSights().filter(s=>s.sel);\n"
"  show('fix');\n"
"  if(sel.length<2){ $('fixout').innerHTML='<p class=\"hint\">Select at least two sights.</p>'; return; }\n"
"  const p=new URLSearchParams(); p.set('n',sel.length);\n"
"  let qs='n='+sel.length;\n"
"  sel.forEach((s,i)=>{ qs+='&'+query(s,i); });\n"
"  const r=await (await fetch('/api/fix?'+qs)).json();\n"
"  if(r.error){ $('fixout').innerHTML='<p class=\"err\">'+r.error+'</p>'; return; }\n"
"  let h=`<p class=\"hint\">Fix at ${r.fy}-${pad(r.fmo,2)}-${pad(r.fd,2)}\n"
"     ${pad(r.fh,2)}:${pad(r.fmi,2)}:${pad(Math.round(r.fs),2)} UTC from ${r.lops.length} lines</p>`;\n"
"  h+='<table class=\"lops\"><thead><tr><th>body</th><th>Zn</th><th>a</th><th>advanced</th><th>residual</th></tr></thead><tbody>';\n"
"  r.lops.forEach(l=>{\n"
"    h+=`<tr><td>${l.name}</td><td>${pad(Math.round(l.zn),3)}\\u00b0</td>\n"
"      <td>${num(Math.abs(l.intercept_nm),1)} ${l.intercept_nm>=0?'T':'A'}</td>\n"
"      <td>${l.advanced_nm>0.05?num(l.advanced_nm,1)+' NM '+pad(Math.round(l.advanced_brg),3)+'\\u00b0':'\\u2014'}</td>\n"
"      <td>${mins(l.residual_nm*60)==='0.0\\u2032'?num(l.residual_nm,2):num(l.residual_nm,2)} NM</td></tr>`;\n"
"  });\n"
"  h+='</tbody></table>';\n"
"  h+=`<p class=\"big\" style=\"margin-top:1rem\">${lat(r.lat)} &nbsp; ${lon(r.lon)}</p>`;\n"
"  h+=`<p class=\"fixline\">RMS ${num(r.rms_nm,2)} NM`;\n"
"  h+= r.have_ellipse\n"
"      ? ` &nbsp;|&nbsp; 1\\u03c3 ellipse ${num(r.semi_major_nm,2)} \\u00d7 ${num(r.semi_minor_nm,2)} NM, major axis ${pad(Math.round(r.ellipse_brg),3)}\\u00b0</p>`\n"
"      : ` &nbsp;|&nbsp; two lines: an intersection, with nothing spare to estimate error</p>`;\n"
"  h+=plotSheet(r);\n"
"  h+='<div class=\"tools\"><button class=\"act\" id=\"usedr\">Use as DR</button></div>';\n"
"  $('fixout').innerHTML=h;\n"
"  $('usedr').onclick=()=>{\n"
"    const st=loadSetup(); st.drlat=r.lat; st.drlon=r.lon;\n"
"    localStorage.setItem(LS_SETUP,JSON.stringify(st));\n"
"    fillSetup(); renderActiveDR(); refresh(); renderList();\n"
"    $('usedr').textContent='DR updated';\n"
"  };\n"
"}\n"
"\n"
"/* ---------- setup ---------- */\n"
"function fillSetup(){\n"
"  const s=loadSetup();\n"
"  $('s_ie').value=s.ie; $('s_iearc').value=s.iearc; $('s_horizon').value=s.horizon;\n"
"  $('s_he').value=s.he; $('s_heunit').value=s.heunit;\n"
"  $('s_temp').value=s.temp; $('s_press').value=s.press;\n"
"  $('s_drlat').value=s.drlat?lat(s.drlat):''; $('s_drlon').value=s.drlon?lon(s.drlon):'';\n"
"}\n"
"function saveSetup(){\n"
"  const s={ie:parseFloat($('s_ie').value)||0,iearc:$('s_iearc').value,\n"
"    horizon:$('s_horizon').value,he:parseFloat($('s_he').value)||0,\n"
"    heunit:$('s_heunit').value,limb:'ll',\n"
"    temp:parseFloat($('s_temp').value)||10,press:parseFloat($('s_press').value)||1010,\n"
"    drlat:parsePos($('s_drlat').value),drlon:parsePos($('s_drlon').value)};\n"
"  localStorage.setItem(LS_SETUP,JSON.stringify(s));\n"
"  fillSetup(); renderActiveDR();\n"
"  $('setupmsg').textContent='Saved in this browser.';\n"
"  refresh(); refreshAlmanac();\n"
"}\n"
"\n"
"/* ---------- annual book ---------- */\n"
"let bookTimer;\n"
"let bookRequest=0, bookStarting=false;\n"
"const bookSections=['sun_moon','planets','stars','events','increments','corrections'];\n"
"function renderBook(s){\n"
"  const busy=s.state==='running';\n"
"  $('book_options').disabled=busy;\n"
"  $('book_build').disabled=busy || !s.available;\n"
"  $('book_engine').textContent=s.engine || '';\n"
"  $('book_progress').hidden=!(busy || s.state==='done');\n"
"  $('book_progress').value=s.percent || 0;\n"
"  $('book_download').hidden=s.state!=='done';\n"
"  $('book_path').textContent=s.state==='done'?s.path:'';\n"
"  if(s.state==='done'){\n"
"    $('book_status').textContent='Book saved.';\n"
"    $('book_download').href='/book/download?id='+encodeURIComponent(s.id);\n"
"    $('book_download').download=s.filename;\n"
"    $('book_download').textContent='Download '+s.filename;\n"
"  }else if(busy){\n"
"    $('book_status').textContent=s.percent+'% · '+s.stage;\n"
"  }else if(s.state==='error'){\n"
"    $('book_status').textContent=s.error;\n"
"  }else{\n"
"    $('book_status').textContent=s.available?'Choose a year and sections.':\n"
"      'The book builder is missing. Run make navalm-book and keep it beside navalm.';\n"
"  }\n"
"  clearTimeout(bookTimer);\n"
"  if(busy) bookTimer=setTimeout(refreshBook,700);\n"
"}\n"
"async function refreshBook(){\n"
"  if(bookStarting) return;\n"
"  const request=++bookRequest;\n"
"  clearTimeout(bookTimer);\n"
"  try{\n"
"    const response=await fetch('/api/book');\n"
"    if(!response.ok) throw new Error('Could not check book progress.');\n"
"    const s=await response.json();\n"
"    if(request!==bookRequest) return;\n"
"    renderBook(s);\n"
"  }catch(e){\n"
"    if(request!==bookRequest) return;\n"
"    $('book_status').textContent='Connection interrupted. Reopen Annual book to check progress.';\n"
"  }\n"
"}\n"
"async function buildBook(){\n"
"  if(!$('book_year').reportValidity()) return;\n"
"  const a=$('book_ageton').checked, f=$('book_formulas').checked;\n"
"  if(!bookSections.some(k=>$('book_'+k).checked) && !a && !f){\n"
"    $('book_status').textContent='Select at least one book section.'; return;\n"
"  }\n"
"  const q=new URLSearchParams({year:$('book_year').value,format:$('book_format').value,\n"
"    reduction:a?(f?'both':'ageton'):(f?'formulas':'none'),shade:$('book_shade').checked?'1':'0'});\n"
"  bookSections.forEach(k=>q.set(k,$('book_'+k).checked?'1':'0'));\n"
"  const request=++bookRequest;\n"
"  bookStarting=true;\n"
"  clearTimeout(bookTimer);\n"
"  $('book_build').disabled=true;\n"
"  $('book_status').textContent='Starting book…';\n"
"  try{\n"
"    const response=await fetch('/api/book?'+q,{method:'POST',headers:{'X-Navalm-Book':'1'}});\n"
"    const s=await response.json();\n"
"    if(request!==bookRequest) return;\n"
"    if(!response.ok) throw new Error(s.error || 'Could not start the book.');\n"
"    renderBook(s);\n"
"  }catch(e){\n"
"    if(request!==bookRequest) return;\n"
"    $('book_build').disabled=false;\n"
"    $('book_status').textContent=e.message;\n"
"  }finally{ bookStarting=false; }\n"
"}\n"
"$('book_year').value=new Date().getUTCFullYear();\n"
"$('book_build').onclick=buildBook;\n"
"\n"
"/* ---------- tabs and wiring ---------- */\n"
"function show(id){\n"
"  document.querySelectorAll('section').forEach(s=>s.classList.toggle('on',s.id===id));\n"
"  document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('on',b.dataset.tab===id));\n"
"  if(id==='list'){ renderList(); }\n"
"  if(id==='almanac'){ refreshAlmanac(); }\n"
"  if(id==='fix'){ renderMotion(); }\n"
"  if(id==='book'){ refreshBook(); }\n"
"}\n"
"document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.tab));\n"
"\n"
"['a_body','a_star','a_date','a_time'].forEach(id=>{\n"
"  $(id).addEventListener('input',refreshAlmanac);\n"
"  $(id).addEventListener('change',refreshAlmanac);\n"
"});\n"
"$('a_body').addEventListener('change',()=>{\n"
"  $('a_starwrap').style.display=$('a_body').value==='star'?'':'none';\n"
"});\n"
"$('a_now').onclick=()=>{ setAlmanacNow(); refreshAlmanac(); };\n"
"$('a_naval').onclick=()=>dailyAlmanac('naval');\n"
"$('a_air').onclick=()=>dailyAlmanac('air');\n"
"\n"
"function setNow(){\n"
"  const d=new Date();\n"
"  $('date').value=d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1,2)+'-'+pad(d.getUTCDate(),2);\n"
"  $('time').value=pad(d.getUTCHours(),2)+':'+pad(d.getUTCMinutes(),2)+':'+pad(d.getUTCSeconds(),2);\n"
"}\n"
"\n"
"['body','limb','date','time','hsd','hsm','label',\n"
" 'f_ie','f_iearc','f_horizon','f_he','f_heunit','f_temp','f_press',\n"
" 'f_drlat','f_drlon','f_course','f_speed','f_set','f_drift'].forEach(id=>{\n"
"  $(id).addEventListener('input',()=>{ refresh(); renderActiveDR(); });\n"
"  $(id).addEventListener('change',()=>{ refresh(); renderActiveDR(); });\n"
"});\n"
"$('body').addEventListener('change',()=>{\n"
"  const isStar=$('body').value==='star';\n"
"  $('starwrap').style.display=isStar?'':'none';\n"
"  $('limbwrap').style.display=(['sun','moon'].includes($('body').value))?'':'none';\n"
"});\n"
"$('star').addEventListener('input',()=>{ starMatch(); refresh(); });\n"
"$('now').onclick=()=>{ setNow(); refresh(); };\n"
"$('loaddef').onclick=()=>{\n"
"  const st=loadSetup();\n"
"  $('f_ie').value=st.ie; $('f_iearc').value=st.iearc; $('f_horizon').value=st.horizon;\n"
"  $('f_he').value=st.he; $('f_heunit').value=st.heunit;\n"
"  $('f_temp').value=st.temp; $('f_press').value=st.press;\n"
"  $('f_drlat').value=st.drlat?lat(st.drlat):''; $('f_drlon').value=st.drlon?lon(st.drlon):'';\n"
"  refresh();\n"
"  $('savemsg').textContent='This sight now uses the current setup defaults.';\n"
"};\n"
"$('save').onclick=()=>{\n"
"  const s=formSight();\n"
"  if(!(s.hs>0)){ $('savemsg').textContent='Enter Hs first.'; return; }\n"
"  const arr=loadSights();\n"
"  if(editIndex!==null && editIndex<arr.length){\n"
"    s.sel=arr[editIndex].sel;\n"
"    arr[editIndex]=s;\n"
"    saveSights(arr);\n"
"    const n=editIndex+1;\n"
"    endEdit('Sight '+n+' updated.');\n"
"    renderMotion();\n"
"    show('list');\n"
"    return;\n"
"  }\n"
"  s.sel=true; arr.push(s); saveSights(arr);\n"
"  $('savemsg').textContent='Saved. '+arr.length+' sight'+(arr.length>1?'s':'')+' stored in this browser.';\n"
"  renderList();\n"
"};\n"
"$('cancel').onclick=()=>{ endEdit('Edit cancelled.'); fillSight(null); refresh(); };\n"
"$('dofix').onclick=doFix;\n"
"$('selall').onclick=()=>{ const a=loadSights(); a.forEach(s=>s.sel=true); saveSights(a); renderList(); renderMotion(); };\n"
"$('clear').onclick=()=>{ if(confirm('Remove every stored sight?')){ saveSights([]); renderList(); renderMotion(); } };\n"
"$('export').onclick=()=>{ const t=$('io'); t.style.display='block'; t.value=JSON.stringify(loadSights(),null,1); t.select(); };\n"
"$('importbtn').onclick=()=>{\n"
"  const t=$('io');\n"
"  if(t.style.display==='none'){ t.style.display='block'; t.value=''; t.placeholder='paste exported JSON, then press Import again'; return; }\n"
"  try{ const a=JSON.parse(t.value); if(Array.isArray(a)){ saveSights(a); renderList(); t.style.display='none'; } }\n"
"  catch(e){ alert('that is not the exported JSON'); }\n"
"};\n"
"$('s_save').onclick=saveSetup;\n"
"\n"
"(async function init(){\n"
"  try{ const v=await (await fetch('/api/version')).json(); $('ver').textContent='v'+v.version; }catch(e){}\n"
"  setNow(); setAlmanacNow(); fillSetup(); fillSight(null); renderActiveDR();\n"
"  $('limbwrap').style.display='';\n"
"  refresh(); refreshAlmanac(); renderList();\n"
"})();\n"
"</script>\n"
"</body>\n"
"</html>\n"
;
#endif
